 look at each document more carefully\n# The question is: what is the total of fixed maturity issues outstanding as of Jan 31 of each year\n\n# Looking at the 1948 document - it's for Jan 31, 1948\n# Looking at the 1949 document - it's for Jan 31, 1949\n# etc.\n\n# From the page text, I can see:\n# 1948: Total fixed maturity = 46,615 (from the first Total row for year 1948)\n# 1949: Total fixed maturity = 36,068 (from the Total row in 1949 section)\n# 1950: Total fixed maturity = 44,467 (from the Total row in 1950 section)\n# 1951: Total fixed maturity = 40,537 (from the Total row in 1951 section)\n\n# These values are in millions. Let me convert to billions:\nvalues_millions = [46615, 36068, 44467, 40537]\nyears = [1948, 1949, 1950, 1951]\n\nfor y, v in zip(years, values_millions):\n    print(f\"Jan {y}: {v} million = {v/1000:.3f} billion\")\n\n# Now let's fit an OLS regression\nimport numpy as np\n\n# X = year, y = billions\nX = np.array(years)\ny = np.array([v/1000 for v in values_millions])\n\n# Add intercept\nX_with_intercept = np.column_stack([np.ones(len(X)), X])\n\n# OLS: beta = (X'X)^-1 X'y\nbeta = np.linalg.inv(X_with_intercept.T @ X_with_intercept) @ X_with_intercept.T @ y\n\nprint(f\"\\nOLS Results:\")\nprint(f\"Intercept: {beta[0]:.4f}\")\nprint(f\"Slope: {beta[1]:.4f}\")\n\n# Predict for 1952\nX_1952 = np.array([1, 1952])\ny_pred_1952 = X_1952 @ beta\n\nprint(f\"\\nPrediction for Jan 1952: {y_pred_1952:.4f} billion\")\nprint(f\"Rounded to tenths: {round(y_pred_1952, 1)} billion\")\n\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
