:\n    content_1951 = f.read()\n\nprint(\"1948 document (Jan 31, 1948):\")\ntotals_1948 = extract_all_fixed_maturity_totals(content_1948)\nprint(f\"  Fixed maturity totals by year: {totals_1948}\")\nprint(f\"  Sum: {sum(totals_1948)}\")\n\nprint(\"\\n1949 document (Jan 31, 1949):\")\ntotals_1949 = extract_all_fixed_maturity_totals(content_1949)\nprint(f\"  Fixed maturity totals by year: {totals_1949}\")\nprint(f\"  Sum: {sum(totals_1949)}\")\n\nprint(\"\\n1950 document (Jan 31, 1950):\")\ntotals_1950 = extract_all_fixed_maturity_totals(content_1950)\nprint(f\"  Fixed maturity totals by year: {totals_1950}\")\nprint(f\"  Sum: {sum(totals_1950)}\")\n\nprint(\"\\n1951 document (Jan 31, 1951):\")\ntotals_1951 = extract_all_fixed_maturity_totals(content_1951)\nprint(f\"  Fixed maturity totals by year: {totals_1951}\")\nprint(f\"  Sum: {sum(totals_1951)}\")\n\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
