rom each document\nvalues_first = [46615, 36068, 44467, 40537]\nyears = [1948, 1949, 1950, 1951]\n\nfor y, v in zip(years, values_first):\n    print(f\"Jan {y}: {v} million = {v/1000:.3f} billion\")\n\n# OLS\nn = len(years)\nx_mean = sum(years) / n\ny_mean = sum(v/1000 for v in values_first) / n\n\nnumerator = sum((years[i] - x_mean) * (values_first[i]/1000 - y_mean) for i in range(n))\ndenominator = sum((years[i] - x_mean)**2 for i in range(n))\n\nb = numerator / denominator\na = y_mean - b * x_mean\n\ny_1952 = a + b * 1952\n\nprint(f\"\\nPrediction for Jan 1952 (Interpretation 1):\")\nprint(f\"  {y_1952:.4f} billion\")\nprint(f\"  Rounded to tenths: {round(y_1952, 1)} billion\")\n\nprint(\"\\n\" + \"=\" * 60)\nprint(\"Interpretation 2: Sum of ALL 'Total' values from each document\")\nprint(\"=\" * 60)\n# Sum of all fixed maturity amounts from each document\n\n# These are the values I extracted earlier:\n# 1948: [46615, 6127, 2635] = 55377\n# 1949: [36068, 11926] = 47994  \n# 1950: [44467, 5373] = 49840\n# 1951: [40537] = 40537\n\n# Wait, but these sums are wrong because we're missing data\n# The tables are split and I'm not getting all values\n\n# Actually let me reconsider - the table structure is different for each year\n# and shows different maturity years. The FIRST \"Total\" for each document\n# is probably the right measure.\n\n# Actually wait - I realize now that the question is asking for the \n# \"total outstanding\" at each date. But looking at the table, each year's\n# \"Total\" represents what matures THAT year. The sum would be all future\n# amounts.\n\n# However, since we're getting inconsistent sums due to partial data \n# extraction, let me stick with Interpretation 1\n\nprint(\"\\nGoing with Interpretation 1 as the answer.\")\nprint(f\"Final prediction: {round(y_1952, 1)} billion\")\n\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
